import sqlite3
from dataclasses import dataclass


@dataclass
class Reporte:
    """Una respuesta lista para mostrar: título, nombres de columna y filas."""
    titulo: str
    columnas: list[str]
    filas: list[tuple]


class VentasRepositorio:
    """Única clase que habla con SQLite."""

    def __init__(self, con: sqlite3.Connection):
        self.con = con

    def ingresos_por_mes(self, anio: str) -> list[tuple]:
        """Pedidos e ingresos de cada mes del año, sin cancelados."""
        sql = """
            SELECT substr(p.fecha, 1, 7) AS mes,
                   COUNT(DISTINCT p.id),
                   ROUND(SUM(d.cantidad * d.precio_unitario * (1 - d.descuento)))
            FROM pedidos p
            JOIN detalle_pedido d ON d.pedido_id = p.id
            WHERE p.estado <> 'cancelado' AND substr(p.fecha, 1, 4) = ?
            GROUP BY mes
            ORDER BY mes
        """
        return self.con.execute(sql, (anio,)).fetchall()


class Reportes:
    """Arma un Reporte por pregunta usando el repositorio."""

    def __init__(self, repo: VentasRepositorio):
        self.repo = repo

    def ventas_mensuales(self, anio: str) -> Reporte:
        filas = self.repo.ingresos_por_mes(anio)
        return Reporte(f"Ventas por mes de {anio}", ["mes", "pedidos", "ingresos"], filas)


def celda(valor) -> str:
    """Los montos (float) en colones con separador de miles; lo demás, como texto."""
    return f"₡{valor:,.0f}" if isinstance(valor, float) else str(valor)


def imprimir(reporte: Reporte) -> None:
    filas = [[celda(v) for v in fila] for fila in reporte.filas]
    anchos = [max(len(x) for x in [col] + [f[i] for f in filas]) for i, col in enumerate(reporte.columnas)]
    numericas = [isinstance(v, (int, float)) for v in reporte.filas[0]]

    def linea(valores):
        return "  ".join(v.rjust(a) if num else v.ljust(a) for v, a, num in zip(valores, anchos, numericas))

    print(reporte.titulo)
    print(linea(reporte.columnas))
    print(linea(["-" * a for a in anchos]))
    for fila in filas:
        print(linea(fila))


con = sqlite3.connect("tienda.db")
reportes = Reportes(VentasRepositorio(con))
imprimir(reportes.ventas_mensuales("2026"))
con.close()

