import sqlite3

ESQUEMA = """
CREATE TABLE pedidos (id INTEGER PRIMARY KEY, fecha TEXT NOT NULL, estado TEXT NOT NULL);
CREATE TABLE detalle_pedido (
    id INTEGER PRIMARY KEY, pedido_id INTEGER NOT NULL REFERENCES pedidos(id),
    cantidad INTEGER NOT NULL, precio_unitario INTEGER NOT NULL, descuento REAL NOT NULL DEFAULT 0
);
"""


class VentasRepositorio:
    def __init__(self, con: sqlite3.Connection):
        self.con = con

    def ingresos_por_mes(self, anio: str) -> list[tuple]:
        """Ingresos de cada mes del año, sin pedidos cancelados."""
        sql = """
            SELECT substr(p.fecha, 1, 7) AS mes,
                   ROUND(SUM(d.cantidad * d.precio_unitario * (1 - d.descuento)))
            FROM pedidos p JOIN detalle_pedido d ON d.pedido_id = p.id
            WHERE p.estado <> 'cancelado' AND substr(p.fecha, 1, 4) = ?
            GROUP BY mes ORDER BY mes
        """
        return self.con.execute(sql, (anio,)).fetchall()


def repo_de_prueba() -> VentasRepositorio:
    """En pytest esto es una fixture: una base nueva en memoria para cada prueba."""
    con = sqlite3.connect(":memory:")
    con.executescript(ESQUEMA)
    con.executemany("INSERT INTO pedidos VALUES (?, ?, ?)", [
        (1, "2026-01-10", "entregado"),
        (2, "2026-01-20", "cancelado"),
        (3, "2026-02-05", "pagado"),
    ])
    con.executemany("INSERT INTO detalle_pedido VALUES (?, ?, ?, ?, ?)", [
        (1, 1, 2, 5000, 0.0),   # 10 000
        (2, 2, 1, 9000, 0.0),   # cancelado: no cuenta
        (3, 3, 1, 10000, 0.1),  # 9 000 con el descuento
    ])
    return VentasRepositorio(con)


def test_excluye_cancelados():
    assert repo_de_prueba().ingresos_por_mes("2026")[0] == ("2026-01", 10000.0)


def test_aplica_descuento():
    assert repo_de_prueba().ingresos_por_mes("2026")[1] == ("2026-02", 9000.0)


def test_anio_sin_datos_da_lista_vacia():
    assert repo_de_prueba().ingresos_por_mes("2025") == []


# pytest encuentra y corre solo las funciones test_*; aquí las llamamos a mano.
for prueba in (test_excluye_cancelados, test_aplica_descuento, test_anio_sin_datos_da_lista_vacia):
    prueba()
    print("PASA", prueba.__name__)

